<script setup lang="ts">
import { useForm, usePage } from '@inertiajs/vue3';
import { computed, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import Button from '@/Core/Components/Button.vue'; import Checkbox from '@/Core/Components/Checkbox.vue'; import Input from '@/Core/Components/Input.vue'; import Modal from '@/Core/Components/Modal.vue'; import Select from '@/Core/Components/Select.vue'; import Textarea from '@/Core/Components/Textarea.vue';
import { route } from '@/Core/lib/route'; import type { CatalogItemType, Product } from './types';
const props = withDefaults(defineProps<{ product?: Product | null; types: CatalogItemType[] }>(), { product: null }); const open = defineModel<boolean>('open', { default: false }); const { t } = useI18n(); const page = usePage();
const form = useForm({ type: 'product' as CatalogItemType, sku: '', name: '', description: '' as string | null, unit: 'unit', currency: page.props.app.currency, unit_price_amount: 0, tax_bps: 0, is_active: true });
const typeOptions = computed(() => props.types.map((value) => ({ value, label: t(`crm.itemTypes.${value}`) })));
watch(open, (shown) => { if (!shown) return; const item = props.product; form.clearErrors(); form.type = item?.type ?? 'product'; form.sku = item?.sku ?? ''; form.name = item?.name ?? ''; form.description = item?.description ?? ''; form.unit = item?.unit ?? 'unit'; form.currency = item?.currency ?? page.props.app.currency; form.unit_price_amount = item?.unitPriceAmount ?? 0; form.tax_bps = item?.taxBps ?? 0; form.is_active = item?.active ?? true; });
function submit(): void { const settings = { preserveScroll: true, onSuccess: () => { open.value = false; form.reset(); } }; if (props.product) form.put(route('crm.sales.products.update', { product: props.product.id }), settings); else form.post(route('crm.sales.products.store'), settings); }
</script>
<template><Modal v-model:open="open" size="lg" :title="t(product ? 'crm.sales.catalogue.edit' : 'crm.sales.catalogue.add')" :persistent="form.processing"><form id="crm-product-form" class="grid gap-4 sm:grid-cols-2" @submit.prevent="submit"><Input v-model="form.name" class="sm:col-span-2" :label="t('crm.fields.name')" :error="form.errors.name" required maxlength="180" autofocus /><Select v-model="form.type" :options="typeOptions" :label="t('crm.fields.type')" :error="form.errors.type" /><Input v-model="form.sku" :label="t('crm.fields.sku')" :error="form.errors.sku" optional maxlength="80" /><Input v-model="form.unit" :label="t('crm.sales.catalogue.unit')" :error="form.errors.unit" required maxlength="40" /><Input v-model="form.currency" :label="t('crm.fields.currency')" :error="form.errors.currency" required maxlength="3" /><Input v-model="form.unit_price_amount" type="number" min="0" step="1" :label="t('crm.fields.unitPrice')" :error="form.errors.unit_price_amount" required /><Input v-model="form.tax_bps" type="number" min="0" max="10000" :label="t('crm.sales.catalogue.tax')" :error="form.errors.tax_bps" required /><Textarea v-model="form.description" class="sm:col-span-2" :label="t('crm.fields.description')" :error="form.errors.description" optional /><Checkbox v-model="form.is_active" :label="t('crm.status.active')" /></form><template #footer><Button variant="ghost" @click="open = false">{{ t('crm.common.cancel') }}</Button><Button form="crm-product-form" type="submit" variant="primary" :loading="form.processing">{{ t('crm.common.save') }}</Button></template></Modal></template>
